#include <iostream>

int main() {
    int hung = 2;
    int dung = 0;

    // Khai bao cac bien tham chieu (aliases)
    int &ti = hung;
    int &teo = dung;

    ti++; // Tuong duong hung++
    std::cout << hung << " " << ti << "\n";

    teo = ti + hung; // dung = 3 + 3
    dung++;          // Tuong duong teo++
    std::cout << dung << " " << teo << "\n";

    return 0;
}

#include <iostream>

// Ham hoan vi truyen theo tham tri (that bai trong viec doi bien ngoai)
void swapValue(int x, int y) {
    int t = x;
    x = y;
    y = t;
    // x va y o day la cac ban sao cuc bo tren stack
}

int main() {
    int x = 2;
    int y = 5;

    swapValue(x, y);
    // Gia tri cua x va y van giu nguyen
    std::cout << "x: " << x << ", y: " << y << "\n";

    return 0;
}

#include <iostream>
#include <cmath>

// Hoan vi 2 bien bang con tro
void swapPointer(int *p, int *q) {
    int t = *p;
    *p = *q;
    *q = t;
}

// Giai phuong trinh bac hai a*x^2 + b*x + c = 0 (gia su a != 0)
// Tra ve so nghiem: 0 (vo nghiem), 1 (nghiem kep tai x1), 2 (hai nghiem x1, x2)
int solveQuadratic(double a, double b, double c, double *x1, double *x2) {
    double delta = b * b - 4 * a * c;
    if (delta < 0.0) {
        return 0;
    } else if (delta == 0.0) {
        *x1 = -b / (2 * a);
        return 1;
    } else {
        double sqrtDelta = std::sqrt(delta);
        *x1 = (-b + sqrtDelta) / (2 * a);
        *x2 = (-b - sqrtDelta) / (2 * a);
        return 2;
    }
}

int main() {
    int a = 2, b = 5;
    swapPointer(&a, &b);
    std::cout << "Swapped: " << a << " " << b << "\n";

    double r1 = 0.0, r2 = 0.0;
    // Phuong trinh x^2 - 3x + 2 = 0
    int numRoots = solveQuadratic(1.0, -3.0, 2.0, &r1, &r2);
    std::cout << "Roots count: " << numRoots << ", x1: " << r1 << ", x2: " << r2 << "\n";

    return 0;
}
